import{_ as n,o as i,c as t,a2 as s}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"Was ist ApptiveGrid","description":"Die Grundbegriffe von ApptiveGrid — Space, Grid, Eintrag, Feld, Ansicht, Formular, Seite und Flow.","frontmatter":{"title":"Was ist ApptiveGrid","description":"Die Grundbegriffe von ApptiveGrid — Space, Grid, Eintrag, Feld, Ansicht, Formular, Seite und Flow."},"headers":[],"relativePath":"erste-schritte/was-ist-apptivegrid.md","filePath":"erste-schritte/was-ist-apptivegrid.md","lastUpdated":1786083786000}'),a={name:"erste-schritte/was-ist-apptivegrid.md"};function r(l,e,d,o,h,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="was-ist-apptivegrid" tabindex="-1">Was ist ApptiveGrid <a class="header-anchor" href="#was-ist-apptivegrid" aria-label="Permalink to &quot;Was ist ApptiveGrid&quot;">​</a></h1><p>ApptiveGrid ist eine Plattform, mit der Sie ohne Programmierung arbeiten können. Sie verwalten strukturierte Daten, erfassen sie über Formulare, automatisieren Abläufe und stellen das Ergebnis als Portal oder eingebettete Anwendung bereit.</p><p>Diese Seite erklärt die Begriffe, die in der gesamten Dokumentation und in der Oberfläche vorkommen. Wenn Sie neu sind, lesen Sie sie zuerst — alle weiteren Seiten setzen diese Begriffe voraus.</p><h2 id="das-grundmodell-in-vier-schritten" tabindex="-1">Das Grundmodell in vier Schritten <a class="header-anchor" href="#das-grundmodell-in-vier-schritten" aria-label="Permalink to &quot;Das Grundmodell in vier Schritten&quot;">​</a></h2><p>ApptiveGrid folgt einem durchgehenden Ablauf:</p><ol><li><strong>Daten</strong> liegen in einem <strong>Grid</strong> — einer Tabelle.</li><li><strong>Erfassen</strong> geschieht über <strong>Formulare</strong>, die auf ein Grid schreiben.</li><li><strong>Automatisieren</strong> übernehmen <strong>Flows</strong>, die auf Ereignisse reagieren.</li><li><strong>Ausliefern</strong> erfolgt über <strong>Seiten</strong>, die Sie als <strong>Portal</strong> veröffentlichen.</li></ol><p>Alles davon lebt in einem <strong>Space</strong>.</p><h2 id="die-begriffe-im-einzelnen" tabindex="-1">Die Begriffe im Einzelnen <a class="header-anchor" href="#die-begriffe-im-einzelnen" aria-label="Permalink to &quot;Die Begriffe im Einzelnen&quot;">​</a></h2><h3 id="space" tabindex="-1">Space <a class="header-anchor" href="#space" aria-label="Permalink to &quot;Space&quot;">​</a></h3><p>Ein Space ist die oberste Organisationseinheit. Er enthält Grids, Seiten und Flows.</p><p>Der Space ist auch die Einheit, an der Zugriffsrechte, Tarif und Sitzplätze hängen. Wenn Sie jemanden einladen, laden Sie ihn in einen Space ein — nicht in ein einzelnes Grid. Wenn Sie einen Tarif buchen, buchen Sie ihn für einen Space.</p><p>Typische Aufteilung: ein Space pro Team, pro Projekt oder pro Kunde.</p><h3 id="grid" tabindex="-1">Grid <a class="header-anchor" href="#grid" aria-label="Permalink to &quot;Grid&quot;">​</a></h3><p>Ein Grid ist eine Tabelle mit strukturierten Daten. Es entspricht dem, was Sie aus einer Tabellenkalkulation kennen — mit dem Unterschied, dass jede Spalte einen festen Typ hat.</p><p>Ein Space kann beliebig viele Grids enthalten, und Grids können untereinander verknüpft werden.</p><h3 id="eintrag" tabindex="-1">Eintrag <a class="header-anchor" href="#eintrag" aria-label="Permalink to &quot;Eintrag&quot;">​</a></h3><p>Ein Eintrag ist eine Zeile in einem Grid. In der englischen Oberfläche heißt er <em>Entry</em>.</p><div class="tip custom-block"><p class="custom-block-title">Begriffe, die dasselbe meinen</p><p>An einigen Stellen der Oberfläche taucht statt „Eintrag&quot; noch <em>Entity</em> oder <em>Record</em> auf — zum Beispiel beim Spaltentyp <em>Eintrag verknüpfen</em> (englisch <em>Link record</em>). Gemeint ist immer dasselbe: eine Zeile in einem Grid.</p></div><h3 id="feld" tabindex="-1">Feld <a class="header-anchor" href="#feld" aria-label="Permalink to &quot;Feld&quot;">​</a></h3><p>Ein Feld ist eine Spalte eines Grids. Jedes Feld hat einen <strong>Spaltentyp</strong>, der bestimmt, welche Werte zulässig sind und wie sie dargestellt, gefiltert und sortiert werden.</p><p>Es gibt Spaltentypen für Text, Zahlen, Datumsangaben, Auswahllisten, Dateien, Adressen, Unterschriften, Verknüpfungen zu anderen Grids und berechnete Werte. Die vollständige Liste finden Sie in der <a href="/docs/referenz/spaltentypen">Spaltentypen-Referenz</a>.</p><p>Der Begriff <strong>Spalte</strong> meint dasselbe wie Feld. Die Oberfläche verwendet beide.</p><h3 id="ansicht" tabindex="-1">Ansicht <a class="header-anchor" href="#ansicht" aria-label="Permalink to &quot;Ansicht&quot;">​</a></h3><p>Eine Ansicht ist eine bestimmte Darstellung eines Grids. Sie legt fest:</p><ul><li>welche Einträge sichtbar sind (Filter),</li><li>in welcher Reihenfolge sie stehen (Sortierung),</li><li>wie sie gebündelt werden (Gruppierung),</li><li>welche Spalten sichtbar sind und in welcher Reihenfolge.</li></ul><p>Entscheidend: <strong>Eine Ansicht ändert die Daten nicht.</strong> Sie ist eine Brille auf dasselbe Grid. Mehrere Ansichten auf einem Grid zeigen dieselben Einträge unterschiedlich.</p><p>Es gibt sieben Ansichtstypen: Grid-Ansicht (Tabelle), Kanban, Kalender, Karte, Galerie, Liste und Timeline. Details unter <a href="/docs/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a>.</p><div class="warning custom-block"><p class="custom-block-title">Grid und Ansicht nicht verwechseln</p><p>Das ist die häufigste Verständnishürde bei ApptiveGrid.</p><ul><li>Das <strong>Grid</strong> enthält die Daten. Löschen Sie es, sind die Daten weg.</li><li>Eine <strong>Ansicht</strong> enthält nur Anzeigeregeln. Löschen Sie sie, bleiben die Daten erhalten.</li></ul><p>Aber Vorsicht: Formulare und geteilte Links hängen an einer Ansicht. Löschen Sie eine Ansicht, funktionieren die daraus erzeugten Formulare nicht mehr. Die Oberfläche warnt beim Löschen mit dem Hinweis, dass Ihre erstellten Formulare nach dem Löschen nicht mehr funktionieren.</p></div><h3 id="formular" tabindex="-1">Formular <a class="header-anchor" href="#formular" aria-label="Permalink to &quot;Formular&quot;">​</a></h3><p>Ein Formular ist eine Eingabemaske auf ein Grid. Sie wählen aus, welche Felder abgefragt werden, gestalten das Erscheinungsbild und teilen das Formular als Link, QR-Code oder eingebettet auf Ihrer Website.</p><p>Formulare können neue Einträge anlegen oder bestehende Einträge bearbeiten.</p><p>Personen, die ein Formular ausfüllen, brauchen <strong>kein ApptiveGrid-Konto</strong> — sofern Sie den Zugriff nicht ausdrücklich beschränken.</p><h3 id="seite-und-block" tabindex="-1">Seite und Block <a class="header-anchor" href="#seite-und-block" aria-label="Permalink to &quot;Seite und Block&quot;">​</a></h3><p>Eine <strong>Seite</strong> ist eine frei zusammengesetzte Oberfläche. Sie bauen sie aus <strong>Blöcken</strong>: Überschriften, Textabsätzen, Bildern, Eingabefeldern, eingebetteten Ansichten, Auswertungen, Layout-Containern.</p><p>Veröffentlichen Sie eine Seite, entsteht ein <strong>Portal</strong> — eine eigenständige Webseite, die Sie teilen oder in Ihre Website einbetten können.</p><div class="tip custom-block"><p class="custom-block-title">„Seite&quot; hat drei Bedeutungen</p><p>Achten Sie beim Lesen der Oberfläche darauf:</p><ol><li><strong>Seite (Portal)</strong> — eine aus Blöcken gebaute Oberfläche. Darum geht es im Kapitel <a href="/docs/seiten/was-sind-seiten">Seiten und Portale</a>.</li><li><strong>Formularseite</strong> — ein Abschnitt innerhalb eines mehrseitigen Formulars.</li><li><strong>Flow-Seite</strong> — eine Seite, die ein Flow einer Person zur Bearbeitung anzeigt.</li></ol><p>Diese Dokumentation benennt sie immer ausdrücklich.</p></div><h3 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h3><p>Ein Flow ist ein automatisierter Ablauf. Er besteht aus <strong>Schritten</strong>, die nacheinander ausgeführt werden.</p><p>Jeder Flow beginnt mit genau einem <strong>Trigger</strong> — dem auslösenden Ereignis. Zum Beispiel: ein neuer Eintrag wurde angelegt, ein Formular wurde abgesendet, oder ein fremdes System hat einen Aufruf geschickt.</p><p>Danach folgen <strong>Aktionen</strong>: eine E-Mail senden, einen Eintrag aktualisieren, eine Datei erzeugen, ein anderes System aufrufen. <strong>Hilfsschritte</strong> wie <em>Router</em>, <em>Parallel</em> und <em>Wait</em> steuern den Ablauf.</p><p>Eine einzelne Ausführung eines Flows heißt <strong>Durchlauf</strong> (in der Oberfläche <em>Previous runs</em>).</p><h3 id="link" tabindex="-1">Link <a class="header-anchor" href="#link" aria-label="Permalink to &quot;Link&quot;">​</a></h3><p>Ein Link ist eine extern teilbare Adresse. ApptiveGrid erzeugt Links für Formulare, Ansichten, Seiten (Portale), Flow-Starts und Einladungen.</p><p>Alle Links eines Space sind an einer Stelle gesammelt sichtbar — siehe <a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a>. Das ist die wichtigste Seite, wenn Sie prüfen wollen, was von außen erreichbar ist.</p><h2 id="wie-die-teile-zusammenhangen" tabindex="-1">Wie die Teile zusammenhängen <a class="header-anchor" href="#wie-die-teile-zusammenhangen" aria-label="Permalink to &quot;Wie die Teile zusammenhängen&quot;">​</a></h2><p>Ein typischer Aufbau sieht so aus:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Space „Veranstaltungen&quot;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Grid „Anmeldungen&quot;</span></span>
<span class="line"><span>│   ├── Ansicht „Alle Anmeldungen&quot;       (Tabelle)</span></span>
<span class="line"><span>│   ├── Ansicht „Offen&quot;                  (Tabelle, gefiltert)</span></span>
<span class="line"><span>│   ├── Ansicht „Nach Termin&quot;            (Kalender)</span></span>
<span class="line"><span>│   └── Formular „Anmeldung&quot;             → schreibt neue Einträge</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Grid „Veranstaltungen&quot;</span></span>
<span class="line"><span>│   └── verknüpft mit „Anmeldungen&quot;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Flow „Bestätigung senden&quot;</span></span>
<span class="line"><span>│   ├── Trigger: Neuer Eintrag via Formular</span></span>
<span class="line"><span>│   └── Aktion:  E-Mail an die anmeldende Person</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Seite „Teilnehmerportal&quot;             → veröffentlicht als Portal</span></span>
<span class="line"><span>    └── Block: Ansicht „Offen&quot; eingebettet</span></span></code></pre></div><p>Die Anmeldung kommt über das Formular herein, landet als Eintrag im Grid, löst den Flow aus, und ist im Portal sichtbar. Alles im selben Space.</p><h2 id="was-sie-als-nachstes-tun-sollten" tabindex="-1">Was Sie als Nächstes tun sollten <a class="header-anchor" href="#was-sie-als-nachstes-tun-sollten" aria-label="Permalink to &quot;Was Sie als Nächstes tun sollten&quot;">​</a></h2><ul><li><a href="/docs/erste-schritte/oberflaeche">Die Oberfläche im Überblick</a> — wo Sie was finden</li><li><a href="/docs/erste-schritte/schnellstart">In 15 Minuten zur ersten Anwendung</a> — ein durchgehendes Beispiel</li><li><a href="/docs/grids/grid-anlegen">Ihr erstes Grid</a> — wenn Sie direkt mit Daten anfangen wollen</li></ul><p>Alle Begriffe noch einmal kompakt: <a href="/docs/referenz/glossar">Glossar</a>.</p>`,51)])])}const g=n(a,[["render",r]]);export{c as __pageData,g as default};
